  --accent-ghost: #2a2d3e;
  --accent-ghost-hover: #343749;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.4);
