body {
  background-color: var(--bg-primary);
  color: var(--text-primary);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 40px 20px;
}

/* ── Page Header ─────────────────────────────────────────── */
.page-header {
  width: 100%;
  max-width: 900px;
  margin-bottom: 32px;
}

.page-header h1 {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.page-header p {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: 4px;
}

/* ── Image Preview Card ──────────────────────────────────── */
.image-card {
  width: 100%;
  max-width: 900px;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
}

.image-preview {
  width: 100%;
  aspect-ratio: 16 / 9;
  background: linear-gradient(135deg, #1a1d27 0%, #12141e 50%, #0f1117 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.image-preview::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 50% at 30% 40%, rgba(99, 102, 241, 0.12) 0%, transparent 70%),
    radial-gradient(ellipse 50% 60% at 75% 65%, rgba(168, 85, 247, 0.08) 0%, transparent 70%);
}

.image-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  color: var(--text-muted);
  position: relative;
  z-index: 1;
}

.image-placeholder svg {
  opacity: 0.4;
}

.image-placeholder span {
  font-size: 0.8125rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.image-info {
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--border-subtle);
}

.image-meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.image-name {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-primary);
}

.image-details {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.image-actions {
  display: flex;
  gap: 10px;
}

/* ── Buttons ─────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background var(--transition), border-color var(--transition), box-shadow var(--transition), color var(--transition);
  white-space: nowrap;
  user-select: none;
}

.btn-ghost {
  background: transparent;
  border-color: var(--border-muted);
  color: var(--text-secondary);
}

.btn-ghost:hover {
  background: var(--accent-ghost-hover);
  border-color: var(--border-muted);
  color: var(--text-primary);
}

.btn-danger-outline {
  background: transparent;
  border-color: rgba(239, 68, 68, 0.4);
  color: var(--accent-red);
}

.btn-danger-outline:hover {
  background: var(--accent-red-glow);
  border-color: var(--accent-red);
  color: #ff6b6b;
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.1);
}

.btn-danger {
  background: var(--accent-red);
  border-color: var(--accent-red);
  color: #fff;
}

.btn-danger:hover {
  background: var(--accent-red-hover);
  border-color: var(--accent-red-hover);
  box-shadow: 0 4px 14px rgba(239, 68, 68, 0.45);
}

.btn-secondary {
  background: var(--accent-ghost);
  border-color: var(--border-muted);
  color: var(--text-secondary);
}

.btn-secondary:hover {
  background: var(--accent-ghost-hover);
  color: var(--text-primary);
}

