              <path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/>
            </svg>
          </div>
          <div class="modal-title-group">
            <h2 class="modal-title" id="modal-title">Delete image?</h2>
            <p class="modal-subtitle" id="modal-desc">This action cannot be undone.</p>
          </div>
          <button class="modal-close" id="modal-close-btn" aria-label="Close dialog">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round">
              <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
            </svg>
          </button>
        </div>

        <div class="modal-body">
          <div class="modal-thumbnail">
            <div class="modal-thumb-img" aria-hidden="true">
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
                <rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/>
                <polyline points="21 15 16 10 5 21"/>
              </svg>
            </div>
            <div class="modal-thumb-meta">
              <div class="modal-thumb-name">${imageTitle}</div>
              <div class="modal-thumb-size">${imageSize}</div>
            </div>
          </div>
          <p>
            <strong>${imageTitle}</strong> will be permanently removed from your
            library. You won't be able to recover it after deletion.
          </p>
        </div>

        <div class="modal-footer">
          <button class="btn btn-secondary" id="modal-cancel-btn">Cancel</button>
          <button class="btn btn-danger" id="modal-confirm-btn">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <polyline points="3 6 5 6 21 6"/>
              <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/>
            </svg>
            Delete image
          </button>
        </div>
      </div>
    </div>
  `;
}

// ── ImageCard Component ───────────────────────────────────────────────────────

function ImageCard({ title, size, date }) {
  return /* html */`
    <div class="image-card">
      <div class="image-preview" aria-label="Image preview">
        <div class="image-placeholder">
          <svg width="52" height="52" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1" stroke-linecap="round" stroke-linejoin="round">
            <rect x="3" y="3" width="18" height="18" rx="2"/>
            <circle cx="8.5" cy="8.5" r="1.5"/>
            <polyline points="21 15 16 10 5 21"/>
          </svg>
          <span>Preview</span>
        </div>
      </div>
      <div class="image-info">
        <div class="image-meta">
          <div class="image-name">${title}</div>
          <div class="image-details">${size} &nbsp;·&nbsp; Added ${date}</div>
        </div>
        <div class="image-actions">
          <button class="btn btn-ghost">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
              <polyline points="7 10 12 15 17 10"/>
              <line x1="12" y1="15" x2="12" y2="3"/>
            </svg>
            Download
          </button>
          <button class="btn btn-danger-outline trigger" id="delete-trigger" aria-haspopup="dialog">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <polyline points="3 6 5 6 21 6"/>
              <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/>
              <path d="M10 11v6M14 11v6"/>
              <path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/>
            </svg>
            Delete
          </button>
        </div>
      </div>
    </div>
  `;
}

// ── App ───────────────────────────────────────────────────────────────────────

function App() {
  const image = {
    title: 'hero-banner-2026.png',
    size: '2.4 MB · 3840 × 2160',
    date: 'May 3, 2026',
  };

  document.getElementById('app').innerHTML = `
    <header class="page-header">
      <h1>Image Library</h1>
      <p>Manage and preview your uploaded images.</p>
    </header>

    ${ImageCard(image)}
    ${ModalDialog({ imageTitle: image.title, imageSize: image.size })}
  `;

  // ── Event wiring ────────────────────────────────────────────────────────────
  const overlay      = document.getElementById('delete-modal');
  const triggerBtn   = document.getElementById('delete-trigger');
  const closeBtns    = [
    document.getElementById('modal-close-btn'),
    document.getElementById('modal-cancel-btn'),
  ];
  const confirmBtn   = document.getElementById('modal-confirm-btn');

  function openModal() {
    overlay.classList.add('is-open');
    overlay.querySelector('.modal').focus();
  }

  function closeModal() {
    overlay.classList.remove('is-open');
    triggerBtn.focus();
  }

  triggerBtn.addEventListener('click', openModal);

  closeBtns.forEach(btn => btn.addEventListener('click', closeModal));

  // Close on backdrop click
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) closeModal();
  });

  // Close on Escape
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && overlay.classList.contains('is-open')) closeModal();
  });

  confirmBtn.addEventListener('click', () => {
    // Simulate deletion feedback
    confirmBtn.disabled = true;
    confirmBtn.textContent = 'Deleting…';
    setTimeout(() => {
      closeModal();
      confirmBtn.disabled = false;
      confirmBtn.innerHTML = `
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <polyline points="3 6 5 6 21 6"/>
          <path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/>
        </svg>
        Delete image
      `;
      // Visual feedback on the card
      const card = document.querySelector('.image-card');
      if (card) {
        card.style.transition = 'opacity 0.4s, transform 0.4s';
        card.style.opacity = '0.3';
        card.style.transform = 'scale(0.98)';
        card.style.pointerEvents = 'none';
        const name = card.querySelector('.image-name');
        if (name) name.textContent += ' (deleted)';
      }
    }, 900);
  });
}

// ── Boot ──────────────────────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', App);
